import React, { useEffect, useRef } from 'react';
import { useClassFramework } from '../contexts/ClassFrameworkContext';

export function SimpleClassTest() {
  const { addClass, showTooltip, hideTooltip } = useClassFramework();
  const elementRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Add a test class
    addClass({
      id: 'test-class',
      name: 'Test Class',
      description: 'This is a test class',
      icon: '🧪',
      notes: [
        {
          id: 'test-note',
          title: 'Test Note',
          description: 'This is a test note to see if the tooltip works.',
          category: 'Test',
          severity: 'info'
        }
      ]
    });
  }, [addClass]);

  const handleMouseEnter = () => {
    console.log('Simple test mouse enter');
    if (elementRef.current) {
      const rect = elementRef.current.getBoundingClientRect();
      showTooltip('simple-test-element', {
        x: rect.left + rect.width / 2,
        y: rect.top - 10,
        element: elementRef.current
      }, 'test-class');
    }
  };

  const handleMouseLeave = () => {
    console.log('Simple test mouse leave');
    hideTooltip();
  };

  return (
    <div 
      ref={elementRef}
      style={{ 
        position: 'fixed', 
        top: '60px', 
        left: '10px', 
        zIndex: 9999,
        background: 'blue',
        color: 'white',
        padding: '10px',
        cursor: 'help'
      }}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      🧪 SIMPLE TEST - Hover over me!
    </div>
  );
}
